'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 pulse:'M2 12h4l3-8 5 16 4-12 2 4h2', topology:'M5 5h5v5H5zM15 15h5v5h-5zM15 4h5v5h-5zM9 8h6M8 10v7h7', flask:'M9 3h6M10 3v6l-5 9a2 2 0 0 0 2 3h10a2 2 0 0 0 2-3l-5-9V3M8 15h8', traffic:'M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4', brain:'M9 5a3 3 0 0 0-5 3 4 4 0 0 0 0 7 3 3 0 0 0 5 4V5m6 0a3 3 0 0 1 5 3 4 4 0 0 1 0 7 3 3 0 0 1-5 4V5M9 10H6m9 4h4M9 15H6m9-7h3M12 2v20', history:'M3 10a9 9 0 1 1 1 8M3 4v6h6m3-3v6l4 2', play:'m8 4 12 8-12 8V4', save:'M4 3h13l4 4v14H3V3h1m3 0v6h10V3M7 21v-8h10v8', plus:'M12 5v14M5 12h14', link:'m9 15 6-6M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 6 0m0 8a4 4 0 0 0 6 0l5-5a4 4 0 0 0-5-5l-2 2', more:'M5 12h.01M12 12h.01M19 12h.01', close:'m6 6 12 12M6 18 18 6', down:'m6 9 6 6 6-6', upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6', download:'M12 3v13m-5-5 5 5 5-5M3 17v4h18v-4', grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z', fit:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6', minus:'M5 12h14', server:'M4 3h16v7H4zM4 14h16v7H4zM7 6h.01M7 17h.01M11 6h6m-6 11h6', clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', check:'m5 12 4 4L19 6', shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6l8-4m-4 10 3 3 5-6', arrow:'M5 12h14m-5-5 5 5-5 5', info:'M12 11v6m0-10h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', folder:'M3 5h7l2 2h9v14H3V5', trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7', chart:'M4 3v18h17M8 16l4-5 4 2 5-8', reset:'M4 10a8 8 0 1 1 1 7M4 4v6h6', tune:'M5 3v7m0 4v7m7-18v12m0 4v2m7-18v3m0 4v11M2 10h6m1 5h6m1-9h6', compare:'M9 3H3v18h6m6-18h6v18h-6M7 12h10m-3-3 3 3-3 3', file:'M5 2h9l5 5v15H5V2m9 0v6h5M8 12h8m-8 4h8', dot:'M12 3v18M3 12h18', globe:'M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 3M4 16l2 3a8 8 0 0 0 13-2'
};
const icon = (name, cls='') => `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.server}"/></svg>`;
const btn=(text,action,ico='',cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${text}</button>`;
const pct = (v,d=1) => v==null?'—':(v*100).toFixed(d)+'%';
const num = (v,d=0) => v==null?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:d});
const date = v => new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const protocolPill = p => `<span class="pill ${p==='SS7'?'orange':p==='Diameter'?'blue':''}">${esc(p==='M3UA'?'SIGTRAN':p)}</span>`;
const state={page:'topology',project:null,selected:'stp-a',selectionType:'node',run:null,models:[],datasets:[],runs:[],projects:[],sweeps:[],dataset:null,model:null,prediction:null,busy:false,zoom:1,traceFilter:'all',search:'',compare:new Set(),threshold:.5,algorithm:'random_forest',trainTrees:120,contamination:.1,thresholdMode:'validation',trainSeed:42,datasetRuns:12,sweep:null,chartMetric:'latency_p95'};
const kindNames={MSC:'Mobile switching center',STP:'Signaling transfer point',SG:'Signaling gateway',HLR:'Home location register',MME:'Mobility management entity',DRA:'Diameter routing agent',HSS:'Home subscriber server',SCP:'Service control point'};
const incidentNames={node_down:'Отказ узла',link_down:'Разрыв канала',surge:'Всплеск нагрузки',latency:'Рост задержки',loss:'Рост потерь'};
const featureNames={rate:'Интенсивность',delivery_ratio:'Доставка',latency_mean:'Задержка · mean',latency_p95:'Задержка · p95',loss_ratio:'Потери',timeout_ratio:'Тайм-ауты',queue_mean:'Очередь · mean',queue_max:'Очередь · max',utilization:'Утилизация',route_changes:'Смена маршрута'};
let toastTimer;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',error?9500:4000);}
async function api(url,body){const res=await fetch('/api'+url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await res.json();}catch{throw new Error('Сервер вернул некорректный ответ');}if(!res.ok){const detail=data.detail;throw new Error(Array.isArray(detail)?detail.map(d=>`${d.loc.slice(1).join('.')}: ${d.msg}`).join('\n'):detail||'Ошибка запроса');}return data;}
async function job(label,fn){if(state.busy)return;state.busy=true;const start=Date.now();render();const el=document.createElement('div');el.className='operation';el.innerHTML=`<span class="spinner"></span><span>${esc(label)}</span><span class="elapsed">0 с</span>`;document.body.append(el);const timer=setInterval(()=>{const time=$('.elapsed',el);if(time)time.textContent=Math.floor((Date.now()-start)/1000)+' с';},1000);try{await fn();}catch(e){toast(e.message,true);}finally{clearInterval(timer);el.remove();state.busy=false;render();}}
async function refresh(){const [runs,datasets,models,projects,sweeps]=await Promise.all(['run','dataset','model','project','sweep'].map(k=>api('/records/'+k)));Object.assign(state,{runs,datasets,models,projects,sweeps});}
function draft(){try{localStorage.setItem('signal-lab-draft-v1',JSON.stringify(state.project));}catch{toast('Не удалось сохранить черновик в браузере',true);}}
function markChanged(){
 draft();
 const breadcrumb=$('.breadcrumbs b');if(breadcrumb)breadcrumb.textContent=state.project.name;
 const status=$('.workspace-grid>.card:first-child>.card-head>.subtle');if(status)status.innerHTML=stale()?'<span class="pill orange">Есть изменения после прогона</span>':state.run?'<span class="dot"></span> Результаты рассчитаны':'Готова к запуску';
 for(const el of $$('[data-node]')){const n=state.project.nodes.find(n=>n.id===el.dataset.node);if(!n)continue;const texts=$$('text',el);texts[0].textContent=n.name;texts[1].textContent=n.kind+' · '+num(n.capacity)+' msg/s';}
 const selected=state.selectionType==='node'?state.project.nodes.find(n=>n.id===state.selected):null;
 if(selected&&$('.node-badge h3'))$('.node-badge h3').textContent=selected.name;
 for(const el of $$('[data-edge]')){const l=state.project.links.find(l=>l.id===el.dataset.edge);if(l)$('text',el).textContent=l.latency_ms+' ms';}
 $$('.timeline-item').forEach((el,i)=>{const e=state.project.incidents[i];if(!e)return;$('.pill',el).textContent=e.start+' s';$('small',el).textContent=Math.min(state.project.duration,e.start+e.duration)+' s';const bar=$('.timeline-bar i',el);bar.style.left=Math.min(100,e.start/state.project.duration*100)+'%';bar.style.width=Math.max(0,Math.min(e.duration,state.project.duration-e.start)/state.project.duration*100)+'%';});
}
function canonical(v){if(Array.isArray(v))return v.map(canonical);if(v&&typeof v==='object')return Object.fromEntries(Object.keys(v).filter(k=>k!=='x'&&k!=='y').sort().map(k=>[k,canonical(v[k])]));return v;}
function stale(){if(!state.run)return false;return JSON.stringify(canonical(state.project))!==JSON.stringify(canonical(state.run.project));}
function downloadObject(value,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const exportLink=(kind,id,format='json',label='Экспорт')=>`<a class="btn small" href="/api/export/${kind}/${esc(id)}?format=${format}" download>${icon('download')}${esc(label)}</a>`;
function render(){if(!state.project)return;const counts=state.runs.length;const nav=[['topology','topology','Топология'],['experiments','flask','Эксперименты'],['traffic','traffic','Телеметрия'],['ml','brain','ML-детекторы'],['results','history','Результаты']];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="logo">${icon('pulse')}</div><div class="wordmark">SIGNAL<span>LAB</span></div></div><div class="workspace-mini"><div class="box">${icon('folder')}</div><div>Исследовательская среда<small>LOCAL WORKSPACE / 01</small></div></div><div class="side-label">ЛАБОРАТОРИЯ</div><nav class="nav" aria-label="Разделы лаборатории">${nav.map(([id,ico,label])=>`<button data-page="${id}" class="${state.page===id?'active':''}" title="${label}" ${state.page===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-label">${label}</span>${id==='results'?`<span class="count">${counts}</span>`:''}${id==='ml'?'<span class="count">ML</span>':''}</button>`).join('')}</nav><div class="side-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><button class="side-action" data-action="projects" aria-label="Мои проекты" title="Мои проекты">${icon('folder')}<span>Мои проекты</span></button><button class="side-action" data-action="import-project" aria-label="Импорт проекта" title="Импорт проекта">${icon('upload')}<span>Импорт проекта</span></button><div class="side-bottom"><button class="side-action" data-action="about">${icon('info')}О модели лаборатории</button><div class="engine-status"><span class="dot"></span> Simulation engine<span class="version">v1.0</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Рабочая область <span>/</span><b>${esc(state.project.name)}</b>${icon('down')}</div><div class="top-actions"><span class="offline"><span class="dot"></span> Локальная среда</span><button class="icon-btn" data-action="about" aria-label="О лаборатории">${icon('info')}</button><span class="avatar">RS</span></div></header><div class="content">${pageContent()}<footer class="bottom-note"><span>SIGNAL LAB <span style="margin:0 7px;color:#c8d0bc">/</span> Исследуйте. Измеряйте. Проверяйте гипотезы.</span><span>Дискретно-событийная симуляция · SS7 / SIGTRAN / Diameter</span></footer></div></main></div>`;$$('.compute').forEach(b=>{if(state.busy)b.disabled=true;});}
function heading(eyebrow,title,subtitle,actions){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions||''}</div></div>`;}
function pageContent(){switch(state.page){case 'topology':return topologyPage();case 'experiments':return experimentsPage();case 'traffic':return trafficPage();case 'ml':return mlPage();case 'results':return resultsPage();}}
function spark(field){const values=state.run?.windows.map(r=>r[field])||[];if(values.length<2)return '';const max=Math.max(...values,1),min=Math.min(...values);const pts=values.map((v,i)=>`${i/(values.length-1)*95},${29-(v-min)/(max-min||1)*25}`).join(' ');return `<svg class="spark" viewBox="0 0 95 32"><polyline points="${pts}" fill="none" stroke="#92b876" stroke-width="1.6"/></svg>`;}
function kpis(){const s=state.run?.summary;return `<div class="kpis"><div class="kpi"><div class="kpi-label">${icon('topology')}Узлы и соединения</div><div class="kpi-value">${state.project.nodes.filter(n=>n.enabled).length}<small> / ${state.project.nodes.length} узлов</small></div><div class="kpi-foot"><span class="pill">${state.project.links.filter(l=>l.enabled).length} каналов</span> ${state.project.flows.length} потока</div></div><div class="kpi"><div class="kpi-label">${icon('traffic')}Пропускная способность</div><div class="kpi-value">${num(s?.throughput,1)} <small>msg/s</small></div><div class="kpi-foot">${s?num(s.delivered)+' сообщений доставлено':'Запустите эксперимент'}</div>${spark('rate')}</div><div class="kpi"><div class="kpi-label">${icon('clock')}Задержка p95</div><div class="kpi-value">${num(s?.latency_p95,1)} <small>ms</small></div><div class="kpi-foot">${s?'Средняя: '+num(s.latency_mean,1)+' ms':'Очередь + обработка + транспорт'}</div>${spark('latency_p95')}</div><div class="kpi"><div class="kpi-label">${icon('shield')}Доставка сообщений</div><div class="kpi-value">${s?pct(s.delivery_ratio,2):'—'}</div><div class="kpi-foot">${s?'<span class="pill '+(s.loss_ratio>.05?'orange':'')+'">'+pct(s.loss_ratio,2)+' потерь</span> seed '+state.run.seed:'Воспроизводимые измерения'}</div>${spark('delivery_ratio')}</div></div>`;}
function topologyPage(){return heading('NETWORK WORKSPACE','Топология сети','Настройте архитектуру сети и исследуйте поведение сигнального трафика.',`${btn('Сохранить','save','save')}${btn(state.busy?'Вычисление…':'Запустить эксперимент','run','play','primary compute')}`)+kpis()+`<div class="workspace-grid"><section class="card"><div class="card-head"><div><h2>Сетевая карта <span class="pill dark" style="margin-left:7px">${state.project.nodes.length} NODES</span></h2></div><span class="subtle">${stale()?'<span class="pill orange">Есть изменения после прогона</span>':state.run?'<span class="dot"></span> Результаты рассчитаны':'Готова к запуску'}</span></div><div class="topology-toolbar">${btn('Узел','add-node','plus','small')}${btn('Соединение','add-link','link','small')}<div class="toolbar-separator"></div><button class="icon-btn" data-action="layout" aria-label="Автоматически расположить узлы" title="Авторасположение">${icon('grid')}</button><div class="toolbar-spacer"></div><select id="preset-select" aria-label="Шаблон сети"><option value="">Загрузить шаблон</option value="hybrid">Hybrid core</option><option value="ss7">SS7 / SIGTRAN</option><option value="diameter">Diameter EPC</option></select><button class="icon-btn" data-action="export-project" aria-label="Экспорт проекта" title="Экспорт проекта">${icon('download')}</button></div><div class="canvas-wrap">${topologySVG()}<div class="canvas-legend"><span class="legend-item"><i style="background:#d4aa73"></i>SS7 / MTP</span><span class="legend-item"><i style="background:#94ad7e"></i>SIGTRAN / M3UA</span><span class="legend-item"><i style="background:#83acb7"></i>Diameter</span></div><div class="canvas-controls"><button class="icon-btn" data-action="zoom-out" aria-label="Уменьшить">${icon('minus')}</button><button class="icon-btn" data-action="fit" aria-label="Вся сеть">${icon('fit')}</button><button class="icon-btn" data-action="zoom-in" aria-label="Увеличить">${icon('plus')}</button></div></div><div class="canvas-foot"><span><span class="dot"></span> ${state.project.nodes.filter(n=>n.enabled).length} узлов включено <span style="margin:0 8px">·</span> ${state.project.incidents.length} событий в сценарии</span><span>Перетаскивайте узлы · Нажмите для настройки</span></div></section><section class="card inspector">${inspector()}</section></div><div class="monitor-grid"><section class="card"><div class="card-head"><div class="chart-title-row"><h2>Профиль сигнального трафика</h2><span class="chart-key"><i></i> Сообщений / с</span></div><span class="subtle">${state.run?state.run.duration+' s · окно '+state.run.project.window+' s':'Ожидание прогона'}</span></div><div class="chart-container">${state.run?lineChart(state.run.windows,'rate',{color:'#91b76e',height:150,incidents:state.run.project.incidents}):emptyChart()}</div></section><section class="card activity-card"><div class="card-head"><h2>Состояние лаборатории</h2>${icon('pulse')}</div><div class="activity"><div class="activity-item"><span class="activity-dot"></span><div><b>${state.run?'Прогон завершён':'Топология загружена'}</b><small>${state.run?num(state.run.summary.sent)+' сообщений · seed '+state.run.seed:'Гибридная сигнальная сеть'}</small></div></div><div class="activity-item"><span class="activity-dot" style="background:#c8ac7a"></span><div><b>${state.project.incidents.length?'Сценарий с событиями':'Базовый сценарий'}</b><small>${state.project.duration} s · Пуассоновские поступления</small></div></div><div class="activity-item"><span class="activity-dot" style="background:#91b2bc"></span><div><b>ML-модуль готов</b><small>${state.models.length} моделей · ${state.datasets.length} датасетов</small></div></div></div></section></div>`;}
function topologySVG(){const p=state.project;const width=1200/state.zoom,height=700/state.zoom;const vx=(1200-width)/2,vy=(700-height)/2;return `<svg id="topology-svg" class="topology-svg" viewBox="${vx} ${vy} ${width} ${height}" role="group" aria-label="Интерактивная топология сети"><text class="map-label" x="68" y="62">LEGACY / SS7 + SIGTRAN</text><text class="map-label" x="780" y="625">EPC / DIAMETER</text>${p.links.map(l=>{const a=p.nodes.find(n=>n.id===l.source),b=p.nodes.find(n=>n.id===l.target);if(!a||!b)return '';const c=l.protocol==='SS7'?'#cfaa76':l.protocol==='Diameter'?'#84adb8':'#a0b88a';const mx=(a.x+b.x)/2,my=(a.y+b.y)/2;const stats=state.run?.links[l.id];return `<g class="edge ${state.selectionType==='link'&&state.selected===l.id?'selected':''}" data-edge="${esc(l.id)}" tabindex="0" role="button" aria-label="Канал ${esc(a.name)} — ${esc(b.name)}"><path class="hit" d="M${a.x} ${a.y} L${b.x} ${b.y}"/><path class="wire" style="stroke:${c};${!l.enabled?'stroke-dasharray:7 7;opacity:.4':''}" d="M${a.x} ${a.y} L${b.x} ${b.y}"/><rect x="${mx-27}" y="${my-11}" width="54" height="18" rx="5" fill="#fafbf8"/><text x="${mx}" y="${my+1}" text-anchor="middle" fill="#95a585" font-size="10">${l.latency_ms} ms</text><title>${esc(l.protocol)} · ${l.bandwidth_mbps} Mbps · ${num(stats?.messages)} сообщений</title></g>`;}).join('')}${p.nodes.map(n=>{const selected=state.selectionType==='node'&&state.selected===n.id;const blue=['MME','DRA','HSS'].includes(n.kind);const color=blue?'#83a7b3':n.kind==='STP'?'#b8945e':'#85a269';const bg=blue?'#eaf1f3':n.kind==='STP'?'#f6efe2':'#edf4e5';return `<g class="node ${selected?'selected':''}" transform="translate(${n.x},${n.y})" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="Узел ${esc(n.name)}" opacity="${n.enabled?1:.4}"><circle class="node-ring" r="49" fill="none" ${selected?'stroke="#7baf55"':''}/><rect class="node-body" x="-33" y="-31" width="66" height="62" rx="13" fill="${bg}" stroke="${color}55"/><g transform="translate(-15 -15)" stroke="${color}" fill="none" stroke-width="1.5" stroke-linejoin="round"><rect x="2" y="2" width="26" height="11" rx="2"/><rect x="2" y="18" width="26" height="11" rx="2"/><path d="M7 7h2m5 0h8M7 23h2m5 0h8"/></g><circle cx="30" cy="-26" r="4.5" fill="${n.enabled?'#9cbf7e':'#c4c9be'}" stroke="#fafbf8" stroke-width="2"/><text y="69" text-anchor="middle" fill="#607450" font-size="18" font-weight="550">${esc(n.name)}</text><text y="86" text-anchor="middle" fill="#879674" font-size="13">${esc(n.kind)} · ${num(n.capacity)} msg/s</text></g>`;}).join('')}</svg>`;}
function field(label,value,attr,type='number',unit='',extra=''){return `<div class="field"><label>${label}</label><div class="field-unit"><input aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${attr} ${extra}>${unit?`<span>${unit}</span>`:''}</div></div>`;}
function inspector(){if(state.selectionType==='link'){const l=state.project.links.find(l=>l.id===state.selected);if(!l)return '<div class="empty-state">Выберите объект на карте</div>';return `<div class="inspector-top">Параметры соединения ${icon('tune')}</div><div class="inspector-body"><div class="node-badge"><div class="node-avatar">${icon('link')}</div><div><h3>${esc(l.source)} → ${esc(l.target)}</h3><small>${esc(l.id)} / full duplex</small></div></div><div class="field"><label>Транспортный профиль</label><select data-link-field="protocol" aria-label="Транспортный профиль">${['SS7','M3UA','Diameter'].map(x=>`<option ${l.protocol===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Задержка',l.latency_ms,'data-link-field="latency_ms"','number','ms','min="0" max="5000" step="0.1"')}${field('Джиттер · σ',l.jitter_ms,'data-link-field="jitter_ms"','number','ms','min="0" max="1000" step="0.1"')}${field('Полоса канала',l.bandwidth_mbps,'data-link-field="bandwidth_mbps"','number','Mbps','min="0.001" max="100000" step="0.1"')}${field('Вероятность потери',l.loss,'data-link-field="loss"','number','','min="0" max="1" step="0.001"')}<label class="switch-row">Канал включён<input type="checkbox" data-link-field="enabled" ${l.enabled?'checked':''}></label><div class="hint">Двусторонний канал с независимой сериализацией в каждом направлении. Потери применяются к каждому сообщению.</div><div class="danger-zone">${btn('Удалить канал','delete-link','trash','small ghost danger')}</div></div>`;}
const n=state.project.nodes.find(n=>n.id===state.selected);if(!n)return '<div class="empty-state">Выберите узел или канал на карте</div>';const stat=state.run?.nodes[n.id];return `<div class="inspector-top">Параметры узла ${icon('tune')}</div><div class="inspector-body"><div class="node-badge"><div class="node-avatar">${icon('server')}</div><div><h3>${esc(n.name)}</h3><small>${esc(kindNames[n.kind])}</small></div></div>${field('Название узла',n.name,'data-node-field="name"','text','','maxlength="80"')}<div class="field"><label>Тип сетевого элемента</label><select data-node-field="kind" aria-label="Тип сетевого элемента">${Object.keys(kindNames).map(k=>`<option ${n.kind===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="divider"></div>${field('Производительность',n.capacity,'data-node-field="capacity"','number','msg/s','min="1" max="100000"')}${field('Время обработки',n.processing_ms,'data-node-field="processing_ms"','number','ms','min="0" max="1000" step="0.1"')}${field('Лимит очереди',n.queue_limit,'data-node-field="queue_limit"','number','msg','min="0" max="10000" step="1"')}${field(['MME','DRA','HSS'].includes(n.kind)?'Diameter realm':'Point code', ['MME','DRA','HSS'].includes(n.kind)?n.realm:n.point_code,`data-node-field="${['MME','DRA','HSS'].includes(n.kind)?'realm':'point_code'}"`,'text','','maxlength="100"')}<label class="switch-row">Узел включён<input type="checkbox" data-node-field="enabled" ${n.enabled?'checked':''}></label><div class="hint">${stat?'Обработано: '+num(stat.processed)+' · Отброшено: '+num(stat.dropped)+'<br>Максимальная очередь: '+stat.max_queue:'Один сервер обслуживания. Время обслуживания = max(1000 / производительность, время обработки).'}<br>Адреса — метаданные модели.</div><div class="danger-zone">${btn('Удалить узел','delete-node','trash','small ghost danger')}</div></div>`;}
function emptyChart(){return '<div class="chart-empty">Запустите эксперимент, чтобы получить измерения</div>';}
function lineChart(rows,key,{height=170,color='#8dad70',incidents=[],unit='',second=null}={}){if(!rows?.length)return emptyChart();const W=760,H=height,L=46,R=18,T=15,B=30;const values=rows.map(r=>r[key]);const all=second?[...values,...rows.map(r=>r[second])]:values;const max=Math.max(...all,0.01)*1.12;const duration=(rows.at(-1).time||1)+(rows.length>1?rows[1].time-rows[0].time:1);const x=t=>L+t/duration*(W-L-R),y=v=>H-B-v/max*(H-T-B);const points=field=>rows.map(r=>`${x(r.time)},${y(r[field])}`).join(' ');return `<svg class="chart" style="height:${height}px" viewBox="0 0 ${W} ${H}" role="img" aria-label="График ${esc(featureNames[key]||key)}"><defs><linearGradient id="chart-fill-${key}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".17"/><stop offset="100%" stop-color="${color}" stop-opacity=".01"/></linearGradient></defs>${[0,1,2,3].map(i=>{const value=max*i/3;return `<line class="chart-grid" x1="${L}" y1="${y(value)}" x2="${W-R}" y2="${y(value)}"/><text x="${L-9}" y="${y(value)+3}" text-anchor="end">${num(value,value<2?2:0)}</text>`;}).join('')}${incidents.map(e=>`<rect x="${x(e.start)}" y="${T}" width="${Math.max(0,x(Math.min(duration,e.start+e.duration))-x(e.start))}" height="${H-T-B}" fill="#dab578" opacity=".10"><title>${esc(incidentNames[e.kind])} · ${e.start}–${e.start+e.duration} s</title></rect>`).join('')}<polygon points="${L},${H-B} ${points(key)} ${x(rows.at(-1).time)},${H-B}" fill="url(#chart-fill-${key})"/><polyline points="${points(key)}" fill="none" stroke="${color}" stroke-width="1.8" stroke-linejoin="round"/>${second?`<polyline points="${points(second)}" fill="none" stroke="#c3a16b" stroke-width="1.7" stroke-dasharray="5 3"/>`:''}${rows.map(r=>`<circle cx="${x(r.time)}" cy="${y(r[key])}" r="3" fill="${color}" opacity=".85"><title>${r.time} s · ${num(r[key],3)} ${esc(unit)}</title></circle>`).join('')}${[0,1,2,3,4,5].map(i=>`<text x="${x(duration*i/5)}" y="${H-8}" text-anchor="middle">${num(duration*i/5)} s</text>`).join('')}</svg>`;}
function experimentsPage(){const p=state.project;return heading('EXPERIMENT DESIGN','Конструктор экспериментов','Управляйте нагрузкой, планируйте отказы и проверяйте устойчивость сети.',`${btn('Экспорт JSON','export-project','download')}${btn('Запустить','run','play','primary compute')}`)+`<div class="wide-grid"><div class="stack"><section class="card"><div class="card-head"><h2>Потоки сигнальных сообщений</h2>${btn('Добавить поток','add-flow','plus','small')}</div><div class="section-intro">Пуассоновские поступления с заданной интенсивностью. SS7 и M3UA используют общий домен маршрутизации; Diameter — отдельный.</div><div class="table-wrap"><table><thead><tr><th>Источник → назначение</th><th>Операция</th><th>msg/s</th><th>Байт</th><th>Тайм-аут, ms</th><th></th></tr></thead><tbody>${p.flows.map(f=>`<tr><td>${esc(f.source)} → ${esc(f.target)}<small>${protocolPill(f.protocol)}</small></td><td>${esc(f.operation)}</td><td><input aria-label="Интенсивность ${esc(f.id)}" data-flow="${esc(f.id)}" data-field="rate" type="number" min="0" max="3000" step="1" value="${f.rate}"></td><td><input aria-label="Размер сообщения ${esc(f.id)}" data-flow="${esc(f.id)}" data-field="message_bytes" type="number" min="32" max="65536" step="1" value="${f.message_bytes}"></td><td><input aria-label="Тайм-аут ${esc(f.id)}" data-flow="${esc(f.id)}" data-field="timeout_ms" type="number" min="1" max="30000" value="${f.timeout_ms}"></td><td><button class="icon-btn" data-action="delete-flow" data-id="${esc(f.id)}" aria-label="Удалить поток">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><h2>События сценария <span class="pill dark">${p.incidents.length}</span></h2>${btn('Запланировать','add-incident','plus','small')}</div>${p.incidents.length?`<div class="table-wrap"><table><thead><tr><th>Событие / объект</th><th>Начало, s</th><th>Длительность, s</th><th>Множитель</th><th></th></tr></thead><tbody>${p.incidents.map((e,i)=>`<tr><td>${esc(incidentNames[e.kind])}<small>${esc(e.target)}</small></td><td><input aria-label="Начало события" data-incident="${i}" data-field="start" type="number" min="0" max="${p.duration-1}" step="1" value="${e.start}"></td><td><input aria-label="Длительность события" data-incident="${i}" data-field="duration" type="number" min="1" max="600" value="${e.duration}"></td><td>${['node_down','link_down'].includes(e.kind)?'—':`<input aria-label="Множитель события" data-incident="${i}" data-field="magnitude" type="number" min="0" max="100" step="0.5" value="${e.magnitude}">`}</td><td><button class="icon-btn" data-action="delete-incident" data-index="${i}" aria-label="Удалить событие">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>${p.incidents.map(e=>`<div class="timeline-item"><span class="pill orange">${e.start} s</span><b>${esc(incidentNames[e.kind])}</b><div class="timeline-bar"><i style="left:${Math.min(100,e.start/p.duration*100)}%;width:${Math.max(0,Math.min(e.duration,p.duration-e.start)/p.duration*100)}%"></i></div><small>${Math.min(p.duration,e.start+e.duration)} s</small></div>`).join('')}`:`<div class="empty-state">${icon('flask')}<h3>Базовый режим сети</h3><p>Добавьте отказ узла, разрыв канала, всплеск нагрузки или деградацию транспорта.</p>${btn('Добавить событие','add-incident','plus','small')}</div>`}<div class="legend-note">События действуют на интервале [начало, конец). Пересекающиеся множители одного типа объединяются через максимум.</div></section><section class="card"><div class="card-head"><h2>Параметрическое исследование</h2><span class="pill">BATCH RUN</span></div><div class="settings-card"><p class="subtle">Сравните сеть при разных уровнях нагрузки. В каждой группе используются одинаковые seed; повторения помогают оценить разброс результатов.</p><div class="two-col"><div class="field"><label>Множители нагрузки через запятую</label><input id="sweep-values" value="0.5, 1, 1.5, 2" placeholder="0.5, 1, 1.5, 2"></div><div class="field"><label>Повторов на точку</label><input id="sweep-reps" type="number" min="1" max="5" value="3"></div></div>${btn('Запустить серию','sweep','flask','primary compute')}</div>${state.sweep?sweepResult(state.sweep):''}</section></div><div class="stack side-tools"><section class="card"><div class="card-head"><h2>Параметры прогона</h2>${icon('tune')}</div><div class="settings-card">${field('Название проекта',p.name,'data-project-field="name"','text','','maxlength="100"')}${field('Длительность',p.duration,'data-project-field="duration"','number','s','min="10" max="600" step="1"')}${field('Seed генератора',p.seed,'data-project-field="seed"','number','','min="0" max="2147483647" step="1"')}${field('Окно агрегации признаков',p.window,'data-project-field="window"','number','s','min="1" max="30" step="1"')}<div class="hint">Одинаковые конфигурация, seed и версии библиотек воспроизводят прогон. Метрики окна привязаны к моменту создания сообщения; очередь обрабатывается до завершения сообщений.</div></div></section><section class="card"><div class="card-head"><h2>Что исследовать</h2></div><div class="info-list"><h3>Устойчивость маршрутизации</h3>Отключите STP Alpha и измерьте доставку через резервный путь.<h3>Предел производительности</h3>Уменьшите capacity HLR и запустите серию по нагрузке.<h3>Чувствительность детектора</h3>Меняйте масштаб событий и сравнивайте recall с ложными срабатываниями.</div></section></div></div>`;}
function sweepResult(s){return `<div class="result-subhead">${s.groups.length} точек · среднее ± приближённый 95% интервал (нормальное приближение)</div><div class="table-wrap"><table><thead><tr><th>Нагрузка</th><th>p95, ms</th><th>Доставка</th><th>msg/s</th></tr></thead><tbody>${s.groups.map(g=>`<tr><td>× ${g.multiplier}<small>n = ${g.n}</small></td><td>${num(g.latency_p95,1)} ${g.latency_p95_ci95==null?'':'± '+num(g.latency_p95_ci95,1)}</td><td>${pct(g.delivery_ratio,2)}</td><td>${num(g.throughput,1)}</td></tr>`).join('')}</tbody></table></div><div class="section-intro">${exportLink('sweep',s.id,'csv','Выгрузить серию')}</div>`;}
function trafficPage(){const r=state.run;return heading('OBSERVABILITY','Телеметрия и сообщения','Окна признаков, маршруты и журнал прохождения сообщений.',r?`${exportLink('run',r.id,'csv','Окна CSV')}${exportLink('run',r.id,'json','Полный JSON')}`:btn('Запустить','run','play','primary compute'))+kpis()+(!r?emptyState('traffic','Нет данных прогона','Запустите эксперимент в текущей топологии.'): `<div class="stack"><div class="card"><div class="card-head"><h2>Задержка обработки</h2><span class="chart-key"><i></i> p95 <i style="background:#c3a16b;margin-left:8px"></i> mean</span></div><div class="chart-container">${lineChart(r.windows,'latency_p95',{height:190,second:'latency_mean',unit:'ms',incidents:r.project.incidents})}</div></div><div class="card"><div class="card-head"><div><h2>Журнал сообщений <span class="pill dark">${num(r.traces.length)} / ${num(r.summary.sent)}</span></h2><div class="meta">Первые ${r.trace_limit} завершённых сообщений · отсортированы по времени создания</div></div><div class="actions"><select id="trace-filter" class="search" style="min-width:110px"><option value="all" ${state.traceFilter==='all'?'selected':''}>Все статусы</option><option value="delivered" ${state.traceFilter==='delivered'?'selected':''}>Доставлены</option><option value="failed" ${state.traceFilter==='failed'?'selected':''}>Не доставлены</option></select><input class="search" id="trace-search" placeholder="Поиск по узлу или операции" value="${esc(state.search)}" aria-label="Поиск в журнале"></div></div><div class="table-wrap" id="trace-table">${traceTable()}</div></div><div class="card"><div class="card-head"><h2>Нагрузка узлов</h2><span class="subtle">По завершённому прогону · ${esc(r.name)}</span></div><div class="table-wrap"><table><thead><tr><th>Узел</th><th>Обработано</th><th>Отброшено</th><th>Макс. очередь</th><th>Занятость сервера *</th></tr></thead><tbody>${Object.entries(r.nodes).map(([id,n])=>`<tr><td>${esc(r.project.nodes.find(x=>x.id===id)?.name||id)}</td><td>${num(n.processed)}</td><td>${num(n.dropped)}</td><td>${n.max_queue}</td><td>${pct(Math.min(1,n.busy_ms/(r.duration*1000)),1)}</td></tr>`).join('')}</tbody></table></div><div class="legend-note">* Суммарное время обслуживания / длительность генерации, с ограничением 100%. Включает обработку хвоста очереди.</div></div></div>`);}
function traceTable(){let rows=[...state.run.traces].sort((a,b)=>a.time-b.time);if(state.traceFilter==='delivered')rows=rows.filter(r=>r.status==='delivered');if(state.traceFilter==='failed')rows=rows.filter(r=>r.status!=='delivered');if(state.search)rows=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(state.search.toLowerCase()));return `<table><thead><tr><th>Время, s</th><th>Протокол</th><th>Операция</th><th>Маршрут</th><th>Задержка, ms</th><th>Статус</th></tr></thead><tbody>${rows.slice(0,150).map(r=>`<tr><td class="inline-code">${r.time.toFixed(3)}</td><td>${protocolPill(r.protocol)}</td><td>${esc(r.operation)}</td><td class="inline-code">${r.route.map(esc).join(' → ')}</td><td>${num(r.latency_ms,2)}</td><td><span class="trace-status ${r.status==='delivered'?'':'bad'}"><span class="dot"></span>${esc(r.status)}</span></td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center;padding:35px">Сообщения не найдены</td></tr>'}</tbody></table><div class="legend-note">Показано ${Math.min(150,rows.length)} из ${rows.length} подходящих записей в выборке. Полные агрегаты включают все сообщения.</div>`;}
function emptyState(ico,title,text){return `<section class="card empty-state">${icon(ico)}<h3>${title}</h3><p>${text}</p></section>`;}
function mlPage(){const d=state.dataset,m=state.model;return heading('MACHINE LEARNING','Мастерская детекторов','От независимых прогонов к обучению и проверке качества на отложенных данных.',`${btn('Импорт CSV','import-csv','upload')}${btn('Сформировать датасет','generate','plus','primary compute')}`)+`<div class="ml-steps"><div class="ml-step ${d?'done':''}"><span>${d?icon('check'):'01'}</span> Подготовка данных</div><div class="ml-step ${m?'done':''}"><span>${m?icon('check'):'02'}</span> Обучение модели</div><div class="ml-step ${m?'done':''}"><span>03</span> Проверка и настройка</div></div><div class="wide-grid"><div class="stack"><section class="card"><div class="card-head"><h2>Датасет телеметрии</h2>${d?`<span class="pill ${d.metadata.source==='csv'?'blue':''}">${d.metadata.source==='csv'?'CSV IMPORT':'SYNTHETIC'}</span>`:'<span class="pill dark">10 ПРИЗНАКОВ</span>'}</div><div class="settings-card"><div class="field"><label for="dataset-select">Активный датасет</label><select id="dataset-select"><option value="">Выберите датасет</option>${state.datasets.map(x=>`<option value="${x.id}" ${d?.id===x.id?'selected':''}>${esc(x.name)} · ${x.metadata?.rows||0} окон</option>`).join('')}</select></div>${d?`<div class="metrics-grid" style="padding:5px 0 15px"><div class="metric-tile"><b>${num(d.metadata.rows)}</b><span>окон признаков</span></div><div class="metric-tile"><b>${d.metadata.runs}</b><span>независимых прогонов</span></div><div class="metric-tile"><b>${d.metadata.positives}</b><span>аномальных окон</span></div><div class="metric-tile"><b>${pct(d.metadata.positives/d.metadata.rows,0)}</b><span>доля аномалий</span></div></div><div class="actions">${exportLink('dataset',d.id,'csv','Датасет CSV')}${exportLink('dataset',d.id,'json','Конфигурации JSON')}</div>`:`<div class="empty-state" style="padding:20px 0">${icon('grid')}<h3>Подготовьте обучающую выборку</h3><p>Генератор создаст независимые прогоны со случайной фоновой нагрузкой, нормальным режимом и событиями сценария.</p></div>`}</div><div class="note-block"><b>Разделение по run_id.</b> Все окна одного прогона попадают только в одну часть: train, validation или test. Метка 1 означает пересечение окна с запланированным событием. Она не гарантирует заметной аномалии в телеметрии.</div></section><section class="card"><div class="card-head"><h2>Конфигурация детектора</h2><span class="pill dark">SCIKIT-LEARN</span></div><div class="settings-card"><div class="model-grid">${[['random_forest','grid','Random Forest','Нелинейный классификатор'],['logistic','chart','Logistic Regression','Линейная базовая модель'],['isolation_forest','shield','Isolation Forest','Обучение на нормальном фоне']].map(([value,ico,title,desc])=>`<label class="model-choice"><input type="radio" name="algorithm" value="${value}" ${state.algorithm===value?'checked':''}>${icon(ico)}<b>${title}</b><span>${desc}</span></label>`).join('')}</div><div class="two-col">${field('Seed обучения',state.trainSeed,'id="train-seed"','number','','min="0" max="2147483647" step="1"')}${state.algorithm==='logistic'?'<div class="field"><label>Баланс классов</label><input value="balanced" readonly></div>':field('Количество деревьев',state.trainTrees,'id="train-trees"','number','','min="20" max="300" step="1"')}</div>${state.algorithm==='isolation_forest'?field('Contamination · доля необычных окон train',state.contamination,'id="contamination"','number','','min="0.001" max="0.5" step="0.01"'):''}${state.algorithm==='isolation_forest'?`<div class="field"><label for="threshold-mode">Метод выбора порога</label><select id="threshold-mode"><option value="validation" ${state.thresholdMode==='validation'?'selected':''}>Максимум F1 на validation</option><option value="contamination" ${state.thresholdMode==='contamination'?'selected':''}>По contamination нормального train</option></select><div class="field-note">Contamination определяет порог только во втором режиме. Validation остаётся отдельной проверочной выборкой.</div></div>`:''}<div class="actions">${btn('Обучить детектор','train','brain','primary compute',!d?'disabled':'')}<span class="subtle">Порог выбирается по F1 на validation</span></div></div></section>${m?modelResult(m):emptyState('brain','Модель ещё не обучена','Выберите датасет и алгоритм. Здесь появятся реальные метрики тестовой выборки, матрица ошибок и важность признаков.')}</div><div class="stack side-tools"><section class="card"><div class="card-head"><h2>Генератор данных</h2>${icon('flask')}</div><div class="settings-card">${field('Количество прогонов',state.datasetRuns,'id="dataset-runs"','number','','min="6" max="24" step="1"')}<div class="field-note">Половина прогонов — нормальный фон, половина — события. Если сценарий пуст, добавляются всплеск, задержка и отказ узла. Нагрузка варьируется на ±25%.</div><div class="divider"></div><div class="field-note">Топология: ${state.project.nodes.length} узлов<br>Длительность: ${state.project.duration} s<br>Окно: ${state.project.window} s<br>План: ≈ ${Math.ceil(state.project.duration/state.project.window)*state.datasetRuns} строк</div><div class="mt">${btn('Сгенерировать','generate','plus','small compute')}</div></div></section><section class="card"><div class="card-head"><h2>Библиотека моделей</h2><span class="pill dark">${state.models.length}</span></div>${state.models.length?`<div class="run-list">${state.models.slice(0,8).map(x=>`<div class="run-item ${m?.id===x.id?'selected':''}"><div class="run-info"><b>${esc(x.metadata?.algorithm||x.name)}</b><small>F1 ${num(x.metadata?.f1,3)} · ${date(x.created)}</small></div><button class="icon-btn" data-action="load-model" data-id="${x.id}" aria-label="Открыть модель">${icon('arrow')}</button></div>`).join('')}</div>`:'<div class="section-intro">Обученные модели сохраняются локально и доступны после перезапуска.</div>'}</section><section class="card"><div class="card-head"><h2>Применение к прогону</h2></div><div class="settings-card"><div class="field"><label for="predict-run">Завершённый эксперимент</label><select id="predict-run"><option value="">Выберите прогон</option>${state.runs.map(x=>`<option value="${x.id}" ${state.run?.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${btn('Проверить модель','predict','shield','small compute',!m?'disabled':'')}<p class="field-note">Применяется выбранная модель с текущим порогом ${m?num(state.threshold,3):'—'}.</p>${state.prediction?`<div class="hint">${state.prediction.windows.filter(x=>x.anomaly).length} из ${state.prediction.windows.length} окон отмечены детектором.<br>${state.prediction.windows.filter(x=>x.anomaly).map(x=>x.time+' s').join(', ')||'Срабатываний нет'}</div>`:''}</div></section></div></div>`;}
function modelResult(m){const mt=m.displayMetrics||m.metrics;return `<section class="card"><div class="card-head"><div><h2>Качество детектора <span class="pill" style="margin-left:7px">TEST SET</span></h2><div class="meta">${esc(m.algorithm)} · ${mt.samples} окон · ${m.split.test.runs.length} независимых прогонов</div></div>${exportLink('model',m.id,'json','Отчёт')}</div><div class="metrics-grid">${[['F1-score',mt.f1],['Precision',mt.precision],['Recall',mt.recall],['ROC AUC',mt.roc_auc]].map(([label,value])=>`<div class="metric-tile"><b>${num(value,3)}</b><span>${label}</span></div>`).join('')}</div><div class="evaluation-grid"><div><h3>Матрица ошибок</h3><div class="confusion"><span></span><span>Прогноз: норма</span><span>Прогноз: аномалия</span><span>Норма</span><div class="cell">${mt.confusion[0][0]}<span class="subtle"> TN</span></div><div class="cell error">${mt.confusion[0][1]}<span class="subtle"> FP</span></div><span>Аном.</span><div class="cell error">${mt.confusion[1][0]}<span class="subtle"> FN</span></div><div class="cell">${mt.confusion[1][1]}<span class="subtle"> TP</span></div></div><div class="range-label"><span>Порог срабатывания</span><b id="threshold-value">${num(state.threshold,3)}</b></div><input class="threshold" id="threshold-slider" aria-label="Порог детектора" type="range" min="0" max="1" step="0.005" value="${state.threshold}"><div class="field-note">Исходный порог (${m.training_config?.threshold_mode==='contamination'?'contamination':'validation'}): ${num(m.threshold,3)}. При ручной настройке по test метрики становятся исследовательскими; для итоговой оценки нужен новый датасет.</div></div><div><h3>${m.importance.length?'Важность признаков':'Особенности Isolation Forest'}</h3>${m.importance.length?`<div class="bars" style="padding:5px 0">${m.importance.slice(0,7).map(x=>`<div class="bar-row"><span>${esc(featureNames[x.feature]||x.feature)}</span><div class="bar-track"><i style="width:${x.value/(m.importance[0].value||1)*100}%"></i></div><span>${num(x.value,2)}</span></div>`).join('')}</div>`:'<p class="subtle">Обучается только на нормальных окнах train. Порог выбирается по validation F1 или по contamination, согласно конфигурации обучения. Важность признаков для этой модели не вычисляется.</p>'}<div class="hint">Train: ${m.split.train.samples} · Validation: ${m.split.validation.samples} · Test: ${m.split.test.samples}<br>PR AUC: ${num(mt.pr_auc,3)} · FPR: ${pct(mt.false_positive_rate,1)}<br>scikit-learn ${esc(m.sklearn_version)} · seed ${m.seed}</div></div></div><div class="note-block">Синтетические результаты характеризуют эту модель сети и выбранный сценарий. Для оценки на реальной сети импортируйте независимо размеченную телеметрию и сохраняйте разделение по экспериментам.</div></section>`;}
function resultsPage(){const r=state.run;return heading('RESEARCH HISTORY','Результаты исследований','Сохранённые прогоны, сравнение конфигураций и воспроизводимые измерения.',`${btn('Сравнить выбранные','compare','compare','',state.compare.size<2?'disabled':'')}${btn('Новый прогон','run','play','primary compute')}`)+`<div class="wide-grid"><div class="stack"><section class="card"><div class="card-head"><h2>Журнал экспериментов</h2><span class="pill dark">${state.runs.length} RUNS</span></div>${state.runs.length?`<div class="run-list">${state.runs.map(x=>`<div class="run-item ${r?.id===x.id?'selected':''}"><input type="checkbox" class="compare-check" data-compare="${x.id}" aria-label="Выбрать для сравнения ${esc(x.name)}" ${state.compare.has(x.id)?'checked':''}><div class="run-icon">${icon('flask')}</div><div class="run-info"><b>${esc(x.name)}</b><small>${date(x.created)} <span class="inline-code">· ${x.id.slice(0,8)}</span></small><div class="row-metrics">${num(x.summary?.sent)} msg <span style="margin:0 8px;color:#c1ceb6">|</span> p95 ${num(x.summary?.latency_p95,1)} ms <span style="margin:0 8px;color:#c1ceb6">|</span> ${pct(x.summary?.delivery_ratio,2)}</div></div><button class="icon-btn" data-action="load-run" data-id="${x.id}" title="Открыть прогон" aria-label="Открыть прогон">${icon('arrow')}</button></div>`).join('')}</div>`:'<div class="empty-state">Пока нет завершённых экспериментов</div>'}</section>${state.comparison?comparisonTable(state.comparison):''}${r?`<section class="card"><div class="card-head"><h2>Прогон · ${esc(r.id.slice(0,8))}</h2>${exportLink('run',r.id,'json','JSON')}</div><div class="chart-container">${lineChart(r.windows,'latency_p95',{height:210,unit:'ms',incidents:r.project.incidents})}</div><div class="section-intro">${btn('Загрузить конфигурацию этого прогона','restore-run','reset','small')}${stale()?'<span class="pill orange" style="margin-left:10px">Текущий проект отличается</span>':''}</div></section>`:''}</div><div class="stack side-tools"><section class="card"><div class="card-head"><h2>Последний выбранный прогон</h2></div>${r?`<div class="settings-card"><div class="field-note">${esc(r.name)}<br>${date(r.created)}</div><div class="divider"></div><div class="metrics-grid" style="padding:0;grid-template-columns:1fr 1fr"><div class="metric-tile"><b>${r.seed}</b><span>seed</span></div><div class="metric-tile"><b>${r.duration} s</b><span>длительность</span></div><div class="metric-tile"><b>${r.project.nodes.length}</b><span>узлов</span></div><div class="metric-tile"><b>${r.project.incidents.length}</b><span>событий</span></div></div><div class="mt actions">${exportLink('run',r.id,'csv','CSV')}${btn('Телеметрия','show-traffic','traffic','small')}</div></div>`:'<div class="section-intro">Запустите симуляцию для получения результатов.</div>'}</section><section class="card"><div class="card-head"><h2>Серии экспериментов</h2></div>${state.sweeps.length?state.sweeps.slice(0,8).map(s=>`<div class="run-item"><div class="run-info"><b>${esc(s.name)}</b><small>${s.metadata?.values.length} точек · ${s.metadata?.repetitions} повторов</small></div><button class="icon-btn" data-action="load-sweep" data-id="${s.id}" aria-label="Открыть серию">${icon('arrow')}</button></div>`).join(''):'<div class="section-intro">Запустите параметрическую серию в конструкторе экспериментов.</div>'}</section><section class="card"><div class="card-head"><h2>Воспроизводимость</h2></div><div class="info-list">Каждый прогон сохраняет полную конфигурацию сети, seed, события, признаки и сводные метрики. JSON-экспорт можно загрузить как новый проект.<br><br>Изменения топологии не переписывают историю прогонов.</div></section></div></div>`;}
function comparisonTable(rows){return `<section class="card"><div class="card-head"><h2>Сравнение выбранных прогонов</h2></div><div class="table-wrap"><table><thead><tr><th>Seed / прогон</th><th>Сообщения</th><th>Доставка</th><th>p95, ms</th><th>msg/s</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.seed}<small>${esc(r.id.slice(0,8))}</small></td><td>${num(r.summary.sent)}</td><td>${pct(r.summary.delivery_ratio,2)}</td><td>${num(r.summary.latency_p95,1)}</td><td>${num(r.summary.throughput,1)}</td></tr>`).join('')}</tbody></table></div></section>`;}

function dialog(title,body,form='',submit='Добавить'){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body">${form?`<form data-form="${form}">${body}<div class="dialog-footer">${btn('Отмена','close-dialog','','small')}<button class="btn primary" type="submit">${submit}</button></div></form>`:body}</div>`;d.showModal();}
function options(list,selected=''){return list.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.id)}</option>`).join('');}
function nodeDialog(){dialog('Добавить сетевой элемент',`${field('Название','New network node','name="name" required','text','','maxlength="80"')}<div class="field"><label>Тип узла</label><select name="kind">${Object.keys(kindNames).map(k=>`<option>${k}</option>`).join('')}</select></div><div class="two-col">${field('Производительность, msg/s',800,'name="capacity" required','number','','min="1" max="100000"')}${field('Лимит очереди',100,'name="queue_limit" required','number','','min="0" max="10000" step="1"')}</div>`,'node');}
function linkDialog(){const ns=state.project.nodes;dialog('Новое соединение',`<div class="two-col"><div class="field"><label>Первый узел</label><select name="source">${options(ns,state.selected)}</select></div><div class="field"><label>Второй узел</label><select name="target">${options(ns,ns.find(n=>n.id!==state.selected)?.id||ns[1].id)}</select></div></div><div class="field"><label>Профиль канала</label><select name="protocol"><option>M3UA</option><option>SS7</option><option>Diameter</option></select></div><div class="two-col">${field('Задержка, ms',8,'name="latency_ms" required','number','','min="0" max="5000" step="0.1"')}${field('Полоса, Mbps',10,'name="bandwidth_mbps" required','number','','min="0.001" max="100000" step="0.1"')}</div>`,'link');}
function flowDialog(){const ns=state.project.nodes;dialog('Новый поток сигнализации',`<div class="two-col"><div class="field"><label>Источник</label><select name="source">${options(ns)}</select></div><div class="field"><label>Назначение</label><select name="target">${options(ns,ns.at(-1).id)}</select></div></div><div class="field"><label>Операция</label><select name="operation">${['MAP UpdateLocation','MAP SendAuthenticationInfo','ISUP IAM','Diameter ULR','Diameter AIR','Diameter CCR'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Домен маршрутизации</label><select name="protocol"><option>M3UA</option><option>SS7</option><option>Diameter</option></select></div><div class="two-col">${field('Интенсивность, msg/s',50,'name="rate" required','number','','min="0" max="3000"')}${field('Размер сообщения, байт',256,'name="message_bytes" required','number','','min="32" max="65536" step="1"')}</div><p class="field-note">Операция служит меткой типа сообщения. Ответы и транзакции протокола в этой версии не моделируются.</p>`,'flow');}
function incidentDialog(){const p=state.project;dialog('Запланировать событие',`<div class="field"><label>Тип события</label><select name="kind" id="incident-kind">${Object.entries(incidentNames).map(([v,n])=>`<option value="${v}">${n}</option>`).join('')}</select></div><div class="field"><label>Объект воздействия</label><select name="target" id="incident-target">${options(p.nodes)}</select></div><div class="two-col">${field('Начало, s',Math.floor(p.duration/3),'name="start" required','number','','min="0" max="'+(p.duration-1)+'" step="1"')}${field('Длительность, s',Math.floor(p.duration/3),'name="duration" required','number','','min="1" max="600" step="1"')}</div>${field('Множитель для нагрузки / задержки / потерь',4,'name="magnitude" required','number','','min="0" max="100" step="0.5"')}<div class="hint">Для отказов множитель не применяется. Маршрут выбирается при отправке; потерянные в пути сообщения не перенаправляются.</div>`,'incident');}
function aboutDialog(){dialog('Модель и границы применимости',`<div class="info-list" style="padding:0"><h3>Локальная исследовательская лаборатория</h3>Дискретно-событийная модель, без подключения к операторским сетям. Каждый сигнал — отдельное сообщение, проходящее через узлы и двусторонние каналы.<h3>Реализовано</h3>Пуассоновская нагрузка, FIFO-очереди с ограничением, производительность узлов, сериализация по полосе, задержка и нормальный джиттер, независимые потери, выбор кратчайшего пути по задержке при отправке, резервные маршруты и события по времени.<h3>Протокольная детализация</h3>SS7/M3UA и Diameter представлены транспортными доменами. MAP/ISUP/Diameter-операции — метки. Point code и realm — метаданные. Полный стек SCTP, ASP/AS, MTP/SCCP/TCAP, GTT, watchdog, request/answer, повторные передачи и транзакционные автоматы не реализованы.<h3>ML и валидация</h3>Random Forest, Logistic Regression и Isolation Forest из scikit-learn. Разделение по независимым прогонам, выбор порога по validation и оценка на test. Модели хранятся локально.<h3>Основания протокольных профилей</h3><a href="https://www.rfc-editor.org/rfc/rfc4666" target="_blank" rel="noreferrer">RFC 4666 · M3UA</a> и <a href="https://www.rfc-editor.org/rfc/rfc6733" target="_blank" rel="noreferrer">RFC 6733 · Diameter</a>. Соответствие этим RFC не заявляется.<h3>Данные</h3>SQLite, датасеты и модели находятся в папке data. Документация API: <a href="/api/docs" target="_blank">/api/docs</a>.</div>`);}
async function fileInput(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.addEventListener('change',()=>resolve(input.files[0]||null),{once:true});input.addEventListener('cancel',()=>resolve(null),{once:true});input.click();});}
async function importProject(){const file=await fileInput('.json,application/json');if(!file)return;if(file.size>2e6)throw new Error('Лимит проекта: 2 МБ');const data=JSON.parse(await file.text());const p=await api('/validate',data.project||data);state.project=p;state.selected=p.nodes[0].id;state.selectionType='node';state.zoom=1;draft();render();toast('Проект импортирован и проверен');}
async function importCSV(){const file=await fileInput('.csv,text/csv');if(!file)return;if(file.size>10e6)throw new Error('Лимит CSV: 10 МБ');const csv=await file.text();await job('Импорт и проверка CSV',async()=>{state.dataset=await api('/datasets/import',{name:file.name.replace(/\.csv$/i,''),csv});await refresh();toast('Датасет импортирован');});}
function projectLibrary(){dialog('Сохранённые проекты',state.projects.length?state.projects.map(p=>`<div class="run-item"><div class="run-info"><b>${esc(p.name)}</b><small>${date(p.created)}</small></div><button class="btn small" data-action="load-project" data-id="${p.id}">Открыть</button></div>`).join(''):'<div class="empty-state">Сохраните текущий проект кнопкой «Сохранить».</div>');}
function checkVisibleInputs(){for(const el of $$('input[type="number"]')){if(!el.checkValidity()){el.reportValidity();return false;}}return true;}
async function action(name,el){switch(name){
case 'run':if(!checkVisibleInputs())return;await job('Расчёт дискретных событий',async()=>{state.run=await api('/simulate',state.project);state.prediction=null;await refresh();toast('Эксперимент завершён: '+num(state.run.summary.sent)+' сообщений');});break;
case 'save':if(!checkVisibleInputs())return;await api('/projects',state.project);await refresh();toast('Проект сохранён в локальной библиотеке');break;
case 'add-node':nodeDialog();break;case 'add-link':linkDialog();break;case 'add-flow':flowDialog();break;case 'add-incident':incidentDialog();break;case 'close-dialog':$('#dialog').close();break;case 'about':aboutDialog();break;case 'projects':projectLibrary();break;
case 'export-project':downloadObject(state.project,'signal-lab-project.json');break;
case 'import-project':await importProject();break;
case 'import-csv':dialog('Импорт телеметрии CSV',`<p class="subtle">UTF-8, разделитель — запятая. Обязательные поля:</p><p class="inline-code" style="line-height:1.9;word-break:break-word">run_id, label, rate, delivery_ratio, latency_mean, latency_p95, loss_ratio, timeout_ratio, queue_mean, queue_max, utilization, route_changes</p><p class="field-note">label: 0 — норма, 1 — аномалия. Минимум 6 независимых run_id и 30 строк. Для обучения в каждой части разбиения должны присутствовать оба класса. Не включайте разные окна одного исходного прогона под разными run_id.</p><div class="dialog-footer">${btn('Выбрать CSV','choose-csv','upload','primary')}</div>`);break;
case 'choose-csv':$('#dialog').close();await importCSV();break;
case 'layout':state.project.nodes.forEach((n,i)=>{n.x=150+(i%4)*290;n.y=150+Math.floor(i/4)*(480/Math.max(1,Math.ceil(state.project.nodes.length/4)-1));});draft();render();break;
case 'zoom-in':state.zoom=Math.min(1.8,state.zoom+.15);render();break;case 'zoom-out':state.zoom=Math.max(.6,state.zoom-.15);render();break;case 'fit':state.zoom=1;render();break;
case 'delete-node':{const n=state.project.nodes.find(n=>n.id===state.selected);if(!n)return;if(state.project.nodes.length<=2)throw new Error('В проекте должно остаться минимум 2 узла');if(state.project.flows.some(f=>f.source===n.id||f.target===n.id))throw new Error('Узел используется потоком. Сначала удалите этот поток в конструкторе экспериментов.');const deletedLinks=state.project.links.filter(l=>l.source===n.id||l.target===n.id).map(l=>l.id);state.project.nodes=state.project.nodes.filter(x=>x.id!==n.id);state.project.links=state.project.links.filter(l=>!deletedLinks.includes(l.id));state.project.incidents=state.project.incidents.filter(e=>e.target!==n.id&&!deletedLinks.includes(e.target));state.selected=state.project.nodes[0].id;draft();render();toast('Узел и связанные каналы удалены');break;}
case 'delete-link':{const id=state.selected;state.project.links=state.project.links.filter(l=>l.id!==id);state.project.incidents=state.project.incidents.filter(e=>e.target!==id||e.kind==='surge'||e.kind==='node_down');state.selectionType='node';state.selected=state.project.nodes[0].id;draft();render();break;}
case 'delete-flow':if(state.project.flows.length<=1)throw new Error('Нужен хотя бы один поток. Сначала добавьте замену.');state.project.flows=state.project.flows.filter(f=>f.id!==el.dataset.id);state.project.incidents=state.project.incidents.filter(e=>e.kind!=='surge'||e.target!==el.dataset.id);draft();render();break;
case 'delete-incident':state.project.incidents.splice(Number(el.dataset.index),1);draft();render();break;
case 'sweep':{if(!checkVisibleInputs())return;const values=$('#sweep-values').value.split(',').map(x=>Number(x.trim()));const repetitions=Number($('#sweep-reps').value);await job('Серия экспериментов по нагрузке',async()=>{state.sweep=await api('/sweep',{project:state.project,values,repetitions});await refresh();toast('Серия завершена: '+state.sweep.results.length+' прогонов');});break;}
case 'generate':{if(!checkVisibleInputs())return;await job('Генерация независимых прогонов и признаков',async()=>{state.dataset=await api('/datasets/generate',{project:state.project,runs:state.datasetRuns,name:state.project.name+' / telemetry'});await refresh();state.page='ml';toast('Датасет готов: '+state.dataset.metadata.rows+' окон');});break;}
case 'train':if(!state.dataset)throw new Error('Выберите датасет');if(!checkVisibleInputs())return;await job('Обучение и проверка детектора',async()=>{state.model=await api('/train',{dataset_id:state.dataset.id,algorithm:state.algorithm,seed:state.trainSeed,trees:state.trainTrees,contamination:state.contamination,threshold_mode:state.algorithm==='isolation_forest'?state.thresholdMode:'validation'});state.threshold=state.model.threshold;state.prediction=null;await refresh();toast('Модель обучена. Test F1: '+num(state.model.metrics.f1,3));});break;
case 'load-model':state.model=await api('/records/model/'+el.dataset.id);state.threshold=state.model.threshold;state.prediction=null;render();break;
case 'predict':{const run_id=$('#predict-run').value;if(!run_id)throw new Error('Выберите завершённый прогон');if(!state.model)throw new Error('Выберите обученную модель');await job('Применение детектора к прогону',async()=>{state.prediction=await api('/predict',{run_id,model_id:state.model.id,threshold:state.threshold});toast('Проверка завершена');});break;}
case 'load-run':state.run=await api('/records/run/'+el.dataset.id);state.prediction=null;render();toast('Прогон выбран. Текущий проект сохранён без изменений.');break;
case 'restore-run':state.project=structuredClone(state.run.project);state.selectionType='node';state.selected=state.project.nodes[0].id;state.page='topology';draft();render();toast('Конфигурация прогона восстановлена');break;
case 'show-traffic':state.page='traffic';render();break;
case 'compare':if(state.compare.size<2)return;state.comparison=await Promise.all([...state.compare].map(id=>api('/records/run/'+id)));render();break;
case 'load-sweep':state.sweep=await api('/records/sweep/'+el.dataset.id);state.page='experiments';render();break;
case 'load-project':{const r=await api('/records/project/'+el.dataset.id);state.project=r.project;state.selectionType='node';state.selected=state.project.nodes[0].id;state.zoom=1;draft();$('#dialog').close();render();toast('Проект загружен');break;}
case 'confirm-preset':state.project=await api('/presets/'+el.dataset.preset);state.selectionType='node';state.selected=state.project.nodes[0].id;state.zoom=1;draft();$('#dialog').close();render();toast('Шаблон загружен');break;
}}
document.addEventListener('click',async e=>{const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;render();return;}const el=e.target.closest('[data-action]');if(el){if(el.disabled)return;try{await action(el.dataset.action,el);}catch(err){toast(err.message,true);}}});
document.addEventListener('change',async e=>{const el=e.target;try{
if(el.matches('input[type="number"]')&&!el.checkValidity()){el.reportValidity();return;}
const value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;
if(el.dataset.nodeField){const n=state.project.nodes.find(n=>n.id===state.selected);n[el.dataset.nodeField]=value;if(el.type==='checkbox'||el.tagName==='SELECT'){draft();render();}else markChanged();}
else if(el.dataset.linkField){state.project.links.find(l=>l.id===state.selected)[el.dataset.linkField]=value;if(el.type==='checkbox'||el.tagName==='SELECT'){draft();render();}else markChanged();}
else if(el.dataset.projectField){state.project[el.dataset.projectField]=value;markChanged();}
else if(el.dataset.flow){state.project.flows.find(f=>f.id===el.dataset.flow)[el.dataset.field]=value;draft();}
else if(el.dataset.incident!==undefined){state.project.incidents[Number(el.dataset.incident)][el.dataset.field]=value;markChanged();}
else if(el.dataset.compare){value?state.compare.add(el.dataset.compare):state.compare.delete(el.dataset.compare);render();}
else if(el.id==='preset-select'&&value){dialog('Загрузить шаблон сети',`<p class="subtle">Текущая рабочая конфигурация будет заменена. Сохранённые проекты и результаты прогонов останутся в библиотеке.</p><div class="dialog-footer">${btn('Отмена','close-dialog','','small')}${btn('Загрузить шаблон','confirm-preset','reset','primary',`data-preset="${esc(value)}"`)}</div>`);el.value='';}
else if(el.id==='incident-kind'){const k=el.value;const list=k==='node_down'?state.project.nodes:k==='surge'?state.project.flows:state.project.links.map(l=>({...l,name:l.source+' ↔ '+l.target}));$('#incident-target').innerHTML=options(list);}
else if(el.id==='dataset-select'){state.dataset=value?await api('/records/dataset/'+value):null;render();}
else if(el.name==='algorithm'){state.algorithm=value;render();}
else if(el.id==='train-seed')state.trainSeed=value;
else if(el.id==='train-trees')state.trainTrees=value;
else if(el.id==='contamination')state.contamination=value;
else if(el.id==='threshold-mode'){state.thresholdMode=value;render();}
else if(el.id==='dataset-runs'){state.datasetRuns=value;render();}
else if(el.id==='trace-filter'){state.traceFilter=value;$('#trace-table').innerHTML=traceTable();}
else if(el.id==='threshold-slider'){const m=state.model;if(!m)return;const threshold=Number(el.value);const met=await api('/models/'+m.id+'/evaluate',{threshold});if(state.model===m&&state.threshold===threshold){m.displayMetrics=met;render();}}
}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='trace-search'){state.search=el.value;$('#trace-table').innerHTML=traceTable();}if(el.id==='threshold-slider'){state.threshold=Number(el.value);$('#threshold-value').textContent=num(state.threshold,3);state.prediction=null;}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const values=Object.fromEntries(new FormData(form));const p=state.project;const uid=prefix=>prefix+'-'+crypto.randomUUID().slice(0,7);try{const next=structuredClone(p);switch(form.dataset.form){
case 'node':{if(p.nodes.length>=60)throw new Error('Лимит: 60 узлов');const n={id:uid('node'),name:values.name,kind:values.kind,x:600,y:300,capacity:Number(values.capacity),queue_limit:Number(values.queue_limit),processing_ms:2,enabled:true,point_code:'2-20-'+(p.nodes.length+1),realm:'lab.example'};next.nodes.push(n);state.selected=n.id;state.selectionType='node';break;}
case 'link':if(values.source===values.target)throw new Error('Выберите разные узлы');if(p.links.some(l=>((l.source===values.source&&l.target===values.target)||(l.source===values.target&&l.target===values.source))&&l.protocol===values.protocol))throw new Error('Такое соединение уже существует');next.links.push({id:uid('link'),...values,latency_ms:Number(values.latency_ms),bandwidth_mbps:Number(values.bandwidth_mbps),jitter_ms:2,loss:.001,enabled:true});break;
case 'flow':if(values.source===values.target)throw new Error('Источник и назначение должны различаться');if(values.operation.startsWith('Diameter')!==(values.protocol==='Diameter'))throw new Error('Выберите операцию и домен одного протокола');next.flows.push({id:uid('flow'),...values,rate:Number(values.rate),message_bytes:Number(values.message_bytes),timeout_ms:1000});break;
case 'incident':if(!values.target)throw new Error('Нет подходящего объекта для этого события');next.incidents.push({kind:values.kind,target:values.target,start:Number(values.start),duration:Number(values.duration),magnitude:Number(values.magnitude)});break;
}state.project=await api('/validate',next);draft();$('#dialog').close();render();toast('Конфигурация обновлена');}catch(err){toast(err.message,true);}});
let drag=null;
document.addEventListener('pointerdown',e=>{const node=e.target.closest('[data-node]');if(!node)return;const svg=$('#topology-svg');if(!svg)return;const n=state.project.nodes.find(n=>n.id===node.dataset.node);const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const local=point.matrixTransform(svg.getScreenCTM().inverse());drag={node,n,svg,dx:local.x-n.x,dy:local.y-n.y,moved:false,startX:e.clientX,startY:e.clientY};node.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag)return;const {svg,n,node,dx,dy}=drag;const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const p=point.matrixTransform(svg.getScreenCTM().inverse());if(Math.abs(e.clientX-drag.startX)+Math.abs(e.clientY-drag.startY)>3)drag.moved=true;if(!drag.moved)return;n.x=Math.round(Math.max(60,Math.min(1140,p.x-dx)));n.y=Math.round(Math.max(80,Math.min(600,p.y-dy)));node.setAttribute('transform',`translate(${n.x},${n.y})`);for(const edge of $$('[data-edge]',svg)){const l=state.project.links.find(l=>l.id===edge.dataset.edge);if(l.source===n.id||l.target===n.id){const a=state.project.nodes.find(v=>v.id===l.source),b=state.project.nodes.find(v=>v.id===l.target);$$('path',edge).forEach(path=>path.setAttribute('d',`M${a.x} ${a.y} L${b.x} ${b.y}`));$('rect',edge).setAttribute('x',(a.x+b.x)/2-27);$('rect',edge).setAttribute('y',(a.y+b.y)/2-11);$('text',edge).setAttribute('x',(a.x+b.x)/2);$('text',edge).setAttribute('y',(a.y+b.y)/2+1);}}});
document.addEventListener('pointerup',()=>{if(!drag)return;state.selected=drag.n.id;state.selectionType='node';if(drag.moved)draft();drag=null;render();});
document.addEventListener('pointercancel',()=>{if(drag){drag=null;draft();render();}});
document.addEventListener('click',e=>{const edge=e.target.closest('[data-edge]');if(edge){state.selected=edge.dataset.edge;state.selectionType='link';render();}});
document.addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const el=e.target.closest('[data-node],[data-edge]');if(!el)return;e.preventDefault();state.selected=el.dataset.node||el.dataset.edge;state.selectionType=el.dataset.node?'node':'link';render();});
async function init(){try{let saved;try{saved=JSON.parse(localStorage.getItem('signal-lab-draft-v1')||'null');}catch{}if(saved){try{state.project=await api('/validate',saved);}catch{toast('Сохранённый черновик не прошёл проверку. Загружен базовый шаблон.',true);}}if(!state.project)state.project=await api('/presets/hybrid');state.selected=state.project.nodes.find(n=>n.id==='stp-a')?.id||state.project.nodes[0].id;await refresh();if(state.runs.length)state.run=await api('/records/run/'+state.runs[0].id);if(state.datasets.length)state.dataset=await api('/records/dataset/'+state.datasets[0].id);if(state.models.length){state.model=await api('/records/model/'+state.models[0].id);state.threshold=state.model.threshold;}render();if(!state.runs.length)await job('Расчёт первого базового прогона',async()=>{state.run=await api('/simulate',state.project);await refresh();});}catch(e){$('#app').innerHTML=`<div class="boot">SIGNAL<span>LAB</span><p>${esc(e.message)}</p><p>Запустите python server.py и обновите страницу.</p></div>`;}}
init();
